+        assert_eq!(plan.groups.len(), 1);
+        assert!(plan.copies.is_empty());
+        let reserved = plan.groups[0]
+            .members
+            .iter()
+            .map(|member| estimated_merge_working_set_bytes(member.stored_bytes))
+            .sum::<u64>();
