+            MetricType::L2,
+            IvfBuildParams::new(2),
+            PQBuildParams {
+                num_sub_vectors: 2,
+                ..Default::default()
+            },
+        );
+        dataset
+            .create_index(
+                &["vector"],
+                IndexType::Vector,
+                Some(VECTOR_INDEX.to_string()),
+                &params,
+                true,
+            )
+            .await
+            .unwrap();
+    }
