+    fn coverage(segments: &[IndexMetadata]) -> RoaringBitmap {
+        segments
+            .iter()
+            .filter_map(|segment| segment.fragment_bitmap.clone())
+            .fold(RoaringBitmap::new(), |acc, bitmap| acc | bitmap)
+    }
+
+    fn task_groups(plan: &OptimizeIndicesPlan) -> Vec<(u32, Vec<u32>)> {
+        plan.tasks
